from pathlib import Path
import re

def read(path): return Path(path).read_text(encoding='utf-8')
def write(path, text): Path(path).write_text(text, encoding='utf-8')
def sub_once(path, pattern, repl, flags=0):
    s=read(path); out,n=re.subn(pattern,repl,s,count=1,flags=flags)
    if n!=1: raise SystemExit(f'Expected one replacement in {path}, got {n}: {pattern[:80]}')
    write(path,out)
def replace_once(path, old, new):
    s=read(path); n=s.count(old)
    if n!=1: raise SystemExit(f'Expected one literal in {path}, got {n}: {old[:80]}')
    write(path,s.replace(old,new,1))

