write('tests/i18n.test.js',r'''/* Translation completeness and interpolation parity are release requirements. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const baseEn=require('../src/locales/en.js'),baseAr=require('../src/locales/ar.js');
const dictionaries={en:{...baseEn},ar:{...baseAr}},context={globalThis:{SultanLocales:dictionaries}};vm.createContext(context);
for(const file of fs.readdirSync(path.join(__dirname,'../src/locales')).filter(x=>x.endsWith('.js')&&!['en.js','ar.js'].includes(x)).sort())vm.runInContext(fs.readFileSync(path.join(__dirname,'../src/locales',file),'utf8'),context,{filename:file});
const en=context.globalThis.SultanLocales.en,ar=context.globalThis.SultanLocales.ar;assert.deepEqual(Object.keys(en).sort(),Object.keys(ar).sort());
for(const key of Object.keys(en)){assert.equal(typeof en[key],'string');assert.equal(typeof ar[key],'string');const vars=s=>[...s.matchAll(/%\{\d+\}/g)].map(x=>x[0]).sort();assert.deepEqual(vars(en[key]),vars(ar[key]),'Placeholder mismatch: '+key);}
console.log(JSON.stringify({translationKeys:Object.keys(en).length,localeFiles:fs.readdirSync(path.join(__dirname,'../src/locales')).filter(x=>x.endsWith('.js')).length,parity:'pass'}));
''')
write('tests/hardening071.test.js',r'''/* Regression coverage for 0.7.1 hardening. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),E=require('../src/engine.js');
let p=E.blank();p.criteria=[{id:'benefit',name:'Benefit',weight:50,low:'low',high:'high',polarity:'benefit'},{id:'cost',name:'Cost',weight:50,low:'low',high:'high',polarity:'cost'}];let a=E.option(),b=E.option();a.id='a';a.title='A';a.scores={benefit:{value:80,note:'x'},cost:{value:20,note:'x'}};b.id='b';b.title='B';b.scores={benefit:{value:70,note:'x'},cost:{value:60,note:'x'}};p.options=[a,b];assert.ok(E.score(p,a).value>E.score(p,b).value);const sw=E.breakEven(p);assert.equal(sw.length,2);for(const x of sw)assert.ok(x.threshold===null||(x.threshold>0&&x.threshold<100));p=E.demo();const ai=E.authorityIssues(p);assert.ok(ai.some(x=>x.entity==='e1'&&x.code==='authorityIssuePending'));assert.ok(ai.some(x=>x.entity==='e2'&&x.code==='authorityIssueUnknownControl'));const checked=E.check(p);assert.ok(checked.some(x=>x.entity==='e1'&&x.section==='enablers'));assert.ok(checked.some(x=>x.entity==='e2'&&x.section==='enablers'));
const ex=fs.readFileSync('src/execution-upgrades.js','utf8'),rv=fs.readFileSync('src/review-visuals.js','utf8'),css=fs.readFileSync('src/execution-upgrades.css','utf8'),cp=fs.readFileSync('src/criteria-polarity.js','utf8');assert.match(ex,/T\('authoritySpaceTitle'\)/);assert.doesNotMatch(ex,/Draft based on user inputs\[\^<\]/);assert.match(ex,/data-report-section="issues"/);assert.match(rv,/matrix-unplotted/);assert.match(rv,/unestimatedYears/);assert.match(css,/inset-inline-start/);assert.match(css,/html\[dir="rtl"\] \.matrix-dot/);assert.doesNotMatch(cp,/E\.score=score/);assert.match(cp,/polarityAnchorWarning/);console.log(JSON.stringify({hardening071:'pass',checks:14}));
''')

